-- Approved repair reservations retain immutable scope and independent holds.
CREATE TABLE doctor_local_presentations (
 id TEXT PRIMARY KEY,
 proposal_id INTEGER NOT NULL REFERENCES doctor_proposals(id),
 task_ref TEXT NOT NULL,
 generation INTEGER NOT NULL,
 digest TEXT NOT NULL,
 presented_at TEXT NOT NULL
);
CREATE TABLE doctor_repairs (
 id TEXT PRIMARY KEY,
 source_id TEXT NOT NULL UNIQUE,
 principal TEXT NOT NULL,
 task_ref TEXT NOT NULL,
 conversation_id INTEGER NOT NULL REFERENCES doctor_conversations(id),
 generation INTEGER NOT NULL,
 proposal_id INTEGER NOT NULL UNIQUE REFERENCES doctor_proposals(id),
 proposal_digest TEXT NOT NULL,
 presentation_id TEXT NOT NULL,
 state TEXT NOT NULL CHECK(state IN ('reserved','quiescing','backed_up','applying','verifying','needs_review','verified','restart_pending','recovered','stopped')),
 revision INTEGER NOT NULL DEFAULT 1,
 fenced INTEGER NOT NULL DEFAULT 0 CHECK(fenced IN(0,1)),
 exclusion_id TEXT NOT NULL DEFAULT '',
 failure TEXT NOT NULL DEFAULT '',
 created_at TEXT NOT NULL,
 updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX doctor_repair_active ON doctor_repairs(task_ref) WHERE state NOT IN ('recovered','stopped');
CREATE TABLE doctor_repair_holds (
 task_ref TEXT PRIMARY KEY,
 repair_id TEXT NOT NULL UNIQUE REFERENCES doctor_repairs(id),
 generation INTEGER NOT NULL,
 active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1))
);
CREATE TABLE doctor_repair_steps (
 repair_id TEXT NOT NULL REFERENCES doctor_repairs(id),
 number INTEGER NOT NULL CHECK(number>0),
 kind TEXT NOT NULL CHECK(kind IN('poll_flag','session_file','worktree_file','run_interrupt','session_unlock','report_completion','watermark_rewind','graph_dispatch_cancel','graph_wait_cancel','graph_attempt_cancel','graph_fail')),
 target TEXT NOT NULL,
 before_value TEXT NOT NULL,
 after_value TEXT NOT NULL,
 source_identity TEXT NOT NULL DEFAULT '',
 state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN('pending','backed_up','write_intent','verified','uncertain')),
 backup BLOB,
 backup_reference TEXT NOT NULL DEFAULT '',
 backup_digest TEXT NOT NULL DEFAULT '',
 observed_after TEXT NOT NULL DEFAULT '',
 PRIMARY KEY(repair_id,number)
);
CREATE TABLE doctor_repair_write_permits (
 repair_id TEXT PRIMARY KEY REFERENCES doctor_repairs(id)
);
CREATE TABLE doctor_restarts (
 repair_id TEXT PRIMARY KEY REFERENCES doctor_repairs(id),
 token TEXT NOT NULL UNIQUE,
 state TEXT NOT NULL CHECK(state IN('pending','dispatched','acknowledged','uncertain')),
 old_instance TEXT NOT NULL,
 new_instance TEXT NOT NULL DEFAULT '',
 report TEXT NOT NULL,
 created_at TEXT NOT NULL
);
CREATE VIEW doctor_held_session_owners AS
SELECT s.id AS session_id,h.repair_id
FROM sessions s JOIN doctor_repair_holds h ON h.active=1
WHERE s.task_ref=h.task_ref
 OR EXISTS(SELECT 1 FROM managed_stories m WHERE m.parent_task=s.task_ref AND h.task_ref=substr(m.parent_task,1,instr(m.parent_task,'#'))||m.issue_number)
 OR EXISTS(SELECT 1 FROM plan_story_drafts p WHERE p.parent=s.task_ref AND h.task_ref=substr(p.parent,1,instr(p.parent,'#'))||p.issue_number);
CREATE TRIGGER doctor_repair_immutable BEFORE UPDATE ON doctor_repairs WHEN NEW.id<>OLD.id OR NEW.source_id<>OLD.source_id OR NEW.principal<>OLD.principal OR NEW.task_ref<>OLD.task_ref OR NEW.conversation_id<>OLD.conversation_id OR NEW.generation<>OLD.generation OR NEW.proposal_id<>OLD.proposal_id OR NEW.proposal_digest<>OLD.proposal_digest OR NEW.presentation_id<>OLD.presentation_id BEGIN SELECT RAISE(ABORT,'immutable doctor repair approval'); END;
CREATE TRIGGER doctor_repair_step_immutable BEFORE UPDATE ON doctor_repair_steps WHEN NEW.repair_id<>OLD.repair_id OR NEW.number<>OLD.number OR NEW.kind<>OLD.kind OR NEW.target<>OLD.target OR NEW.before_value<>OLD.before_value OR NEW.after_value<>OLD.after_value OR NEW.source_identity<>OLD.source_identity BEGIN SELECT RAISE(ABORT,'immutable doctor repair step'); END;
CREATE TRIGGER doctor_repair_no_delete BEFORE DELETE ON doctor_repairs BEGIN SELECT RAISE(ABORT,'retained doctor repair history'); END;
CREATE TRIGGER doctor_repair_step_no_delete BEFORE DELETE ON doctor_repair_steps BEGIN SELECT RAISE(ABORT,'retained doctor repair backup'); END;
CREATE TRIGGER doctor_repair_presentation_immutable BEFORE UPDATE ON doctor_local_presentations BEGIN SELECT RAISE(ABORT,'immutable doctor presentation'); END;
CREATE TRIGGER doctor_hold_acceptance_decisions_insert BEFORE INSERT ON acceptance_decisions WHEN EXISTS(SELECT 1 FROM doctor_repair_holds h WHERE h.active=1 AND (EXISTS(SELECT 1 FROM runs dr JOIN sessions ds ON ds.id=dr.session_id WHERE dr.id=NEW.run_id AND EXISTS(SELECT 1 FROM doctor_held_session_owners dv WHERE dv.session_id=ds.id AND dv.repair_id=h.repair_id))) AND NOT EXISTS(SELECT 1 FROM doctor_repair_write_permits permit WHERE permit.repair_id=h.repair_id)) BEGIN SELECT RAISE(ABORT,'issue held for doctor repair'); END;
